import java.util.*;

class Solution {
    private static final int INF = 2147483647;
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public void wallsAndGates(int[][] rooms) {
        int rows = rooms.length;
        int cols = rooms[0].length;
        Queue<int[]> queue = new ArrayDeque<>();

        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                if (rooms[row][col] == 0) {
                    queue.offer(new int[]{row, col});
                }
            }
        }

        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            for (int[] direction : DIRECTIONS) {
                int nextRow = cell[0] + direction[0];
                int nextCol = cell[1] + direction[1];
                if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) {
                    continue;
                }
                if (rooms[nextRow][nextCol] != INF) {
                    continue;
                }
                rooms[nextRow][nextCol] = rooms[cell[0]][cell[1]] + 1;
                queue.offer(new int[]{nextRow, nextCol});
            }
        }
    }
}

class Solution {
    public void wallsAndGates(int[][] rooms) {
        int rows = rooms.length;
        int cols = rooms[0].length;
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                if (rooms[row][col] == 0) {
                    relax(rooms, row, col, 0);
                }
            }
        }
    }

    private void relax(int[][] rooms, int row, int col, int distance) {
        if (row < 0 || row >= rooms.length || col < 0 || col >= rooms[0].length) {
            return;
        }
        if (rooms[row][col] < distance) {
            return;
        }
        rooms[row][col] = distance;
        relax(rooms, row + 1, col, distance + 1);
        relax(rooms, row - 1, col, distance + 1);
        relax(rooms, row, col + 1, distance + 1);
        relax(rooms, row, col - 1, distance + 1);
    }
}

import java.util.*;

class Solution {
    private static final int INF = 2147483647;
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public void wallsAndGates(int[][] rooms) {
        int rows = rooms.length;
        int cols = rooms[0].length;
        PriorityQueue<int[]> heap = new PriorityQueue<>(Comparator.comparingInt(cell -> cell[2]));

        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                if (rooms[row][col] == 0) {
                    heap.offer(new int[]{row, col, 0});
                }
            }
        }

        while (!heap.isEmpty()) {
            int[] cell = heap.poll();
            int row = cell[0];
            int col = cell[1];
            int distance = cell[2];
            if (distance != rooms[row][col]) {
                continue;
            }
            for (int[] direction : DIRECTIONS) {
                int nextRow = row + direction[0];
                int nextCol = col + direction[1];
                if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) {
                    continue;
                }
                if (rooms[nextRow][nextCol] != INF) {
                    continue;
                }
                int nextDistance = distance + 1;
                rooms[nextRow][nextCol] = nextDistance;
                heap.offer(new int[]{nextRow, nextCol, nextDistance});
            }
        }
    }
}

class Solution {
    private static final int INF = 2147483647;
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public void wallsAndGates(int[][] rooms) {
        int rows = rooms.length;
        int cols = rooms[0].length;
        boolean changed = true;

        while (changed) {
            changed = false;
            for (int row = 0; row < rows; row++) {
                for (int col = 0; col < cols; col++) {
                    if (rooms[row][col] == -1 || rooms[row][col] == 0) {
                        continue;
                    }
                    int best = rooms[row][col];
                    for (int[] direction : DIRECTIONS) {
                        int nextRow = row + direction[0];
                        int nextCol = col + direction[1];
                        if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) {
                            continue;
                        }
                        if (rooms[nextRow][nextCol] == -1 || rooms[nextRow][nextCol] == INF) {
                            continue;
                        }
                        best = Math.min(best, rooms[nextRow][nextCol] + 1);
                    }
                    if (best < rooms[row][col]) {
                        rooms[row][col] = best;
                        changed = true;
                    }
                }
            }
        }
    }
}
